mapper.select:
SELECT dc.defect_type, COUNT(dd.id) AS defect_count, SUM(dd.defect_quantity) AS total_quantity FROM mes_defect_detail dd JOIN mes_defect_code dc ON dd.defect_code = dc.defect_code JOIN mes_quality_task t ON dd.task_id = t.id
AND DATE(t.create_time) >= #{startDate}
AND DATE(t.create_time) <= #{endDate}
GROUP BY dc.defect_type ORDER BY defect_count DESC

SELECT dd.defect_code, dc.defect_name, dc.defect_type, COUNT(dd.id) AS defect_count, SUM(dd.defect_quantity) AS total_quantity FROM mes_defect_detail dd JOIN mes_defect_code dc ON dd.defect_code = dc.defect_code JOIN mes_quality_task t ON dd.task_id = t.id
t.status = 'completed'
AND t.product_code = #{query.productCode}
AND DATE(t.create_time) >= #{query.startDate}
AND DATE(t.create_time) <= #{query.endDate}
GROUP BY dd.defect_code, dc.defect_name, dc.defect_type ORDER BY defect_count DESC

